#include <string>
#include <vector>
#include <algorithm>
#include <cstring>

class Solution {
    int memo[105][105];
    int n;
    int dp(int i, int rem, const std::string& s) {
        if (rem < 0) return 1e9;
        if (i >= n || n - i <= rem) return 0;
        if (memo[i][rem] != -1) return memo[i][rem];
        int res = dp(i + 1, rem - 1, s);
        int diff = 0, same = 0;
        for (int j = i; j < n; ++j) {
            if (s[j] == s[i]) same++;
            else diff++;
            if (diff > rem) break;
            int len = 1 + (same == 1 ? 0 : (same < 10 ? 1 : (same < 100 ? 2 : 3)));
            res = std::min(res, len + dp(j + 1, rem - diff, s));
        }
        return memo[i][rem] = res;
    }
public:
    int getLengthOfOptimalCompression(std::string s, int k) {
        n = s.size();
        std::memset(memo, -1, sizeof(memo));
        return dp(0, k, s);
    }
};

import java.util.*;

class Solution {
    int[][] memo;
    int n;
    private int dp(int i, int rem, String s) {
        if (rem < 0) return 100000;
        if (i >= n || n - i <= rem) return 0;
        if (memo[i][rem] != -1) return memo[i][rem];
        int res = dp(i + 1, rem - 1, s);
        int diff = 0, same = 0;
        for (int j = i; j < n; j++) {
            if (s.charAt(j) == s.charAt(i)) same++;
            else diff++;
            if (diff > rem) break;
            int len = 1 + (same == 1 ? 0 : (same < 10 ? 1 : (same < 100 ? 2 : 3)));
            res = Math.min(res, len + dp(j + 1, rem - diff, s));
        }
        return memo[i][rem] = res;
    }
    public int getLengthOfOptimalCompression(String s, int k) {
        n = s.length();
        memo = new int[n + 1][k + 1];
        for (int[] row : memo) Arrays.fill(row, -1);
        return dp(0, k, s);
    }
}

var getLengthOfOptimalCompression = function(s, k) {
    const n = s.length;
    const memo = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(-1));
    function dp(i, rem) {
        if (rem < 0) return 1e9;
        if (i >= n || n - i <= rem) return 0;
        if (memo[i][rem] !== -1) return memo[i][rem];
        let res = dp(i + 1, rem - 1);
        let diff = 0, same = 0;
        for (let j = i; j < n; j++) {
            if (s[j] === s[i]) same++;
            else diff++;
            if (diff > rem) break;
            const len = 1 + (same === 1 ? 0 : (same < 10 ? 1 : (same < 100 ? 2 : 3)));
            res = Math.min(res, len + dp(j + 1, rem - diff));
        }
        return memo[i][rem] = res;
    }
    return dp(0, k);
};
